select case when salary >= 132000 then 'high' when salary >= 81000 then 'mid' else 'low' end as salary_bucket, sum(salary) as total_salary, sum(sum(salary)) over (order by case when salary >= 132000 then 'high' when salary >= 81000 then 'mid' else 'low' end) as cumulative_salary from employees group by case when salary >= 132000 then 'high' when salary >= 81000 then 'mid' else 'low' end order by total_salary
